import canvasSizes from "./canvas-sizes.json";
import type { Margins, SafeZone } from "./safe-zones";

// The canvas sizes offered when a blank canvas is created:
//
// - Standard: ArtCraft's own generic sizes.
// - One tab per channel in canvas-sizes.json (Social, …): sizes and safe zones
//   that the platforms publish. That file is generated by craft-canvas-size-lib
//   (https://github.com/MaxvonFred/craft-canvas-size-lib), where every
//   value links to its source. Copy it from there; don't edit it here.
// - My presets: sizes the user saves, with safe zones of their own.

export const STANDARD_CHANNEL = "Standard";
export const CUSTOM_CHANNEL = "My presets";
export const CUSTOM_PRESET_MIN_SIZE = 16;
export const CUSTOM_PRESET_MAX_SIZE = 4096;

export interface CanvasSizePreset {
  id: string;
  /** The tab it is listed in: "Standard", "Social", "My presets"… */
  channel: string;
  /** The heading it is listed under: "Square", "Instagram"… */
  group: string;
  name?: string;
  width: number;
  height: number;
  /** Safe zones made for this size. The first is shown when the preset starts a canvas. */
  safeZones: SafeZone[];
  sourceUrl?: string;
}

/** What the user fills in to save a preset. Margins are pixels of the preset's size. */
export interface CustomCanvasPresetInput {
  name: string;
  width: number;
  height: number;
  safeZones: { name: string; margins: Margins }[];
}

/** The shape of canvas-sizes.json, format 1. */
interface CanvasSizeLibraryFile {
  format: number;
  channels: {
    name: string;
    platforms: {
      name: string;
      types: {
        id: string;
        name: string;
        width: number;
        height: number;
        safeZones: string[];
        source: string;
      }[];
    }[];
  }[];
  safeZones: {
    id: string;
    name: string;
    ratio: number[];
    frame: number[];
    margins: Margins;
    covered: { x: number; y: number; width: number; height: number }[];
    source: string;
  }[];
}

const LIBRARY: CanvasSizeLibraryFile = canvasSizes;

export const BUILT_IN_SAFE_ZONES: SafeZone[] = LIBRARY.safeZones.map(
  (zone) => ({
    id: zone.id,
    label: zone.name,
    ratio: { width: zone.ratio[0], height: zone.ratio[1] },
    frame: { width: zone.frame[0], height: zone.frame[1] },
    margins: zone.margins,
    covered: zone.covered,
    mirrorsForRightToLeft: true,
    sourceUrl: zone.source,
  }),
);

export const STANDARD_CANVAS_PRESETS: CanvasSizePreset[] = [
  standard("square-512", "Square", 512, 512),
  standard("square-768", "Square", 768, 768),
  standard("square-1024", "Square", 1024, 1024),
  standard("square-1536", "Square", 1536, 1536),
  standard("landscape-hd", "Landscape", 1280, 720, "HD"),
  standard("landscape-full-hd", "Landscape", 1920, 1080, "Full HD"),
  standard("landscape-qhd", "Landscape", 2560, 1440, "QHD"),
  standard("portrait-720", "Portrait", 720, 1280),
  standard("portrait-1080", "Portrait", 1080, 1920),
];

/** Every built-in preset, Standard first, then the library's channels in its order. */
export const BUILT_IN_CANVAS_PRESETS: CanvasSizePreset[] = [
  ...STANDARD_CANVAS_PRESETS,
  ...LIBRARY.channels.flatMap((channel) =>
    channel.platforms.flatMap((platform) =>
      platform.types.map((type) => ({
        id: type.id,
        channel: channel.name,
        group: platform.name,
        name: type.name,
        width: type.width,
        height: type.height,
        safeZones: type.safeZones.flatMap((id) =>
          BUILT_IN_SAFE_ZONES.filter((zone) => zone.id === id),
        ),
        sourceUrl: type.source,
      })),
    ),
  ),
];

/** What is wrong with a preset the user wants to save; empty when it can be saved. */
export function customPresetProblems(input: CustomCanvasPresetInput): string[] {
  const problems: string[] = [];
  if (!input.name.trim()) {
    problems.push("Give the preset a name.");
  }
  if (!isSize(input.width) || !isSize(input.height)) {
    problems.push(
      `Width and height must be whole numbers from ${CUSTOM_PRESET_MIN_SIZE} to ${CUSTOM_PRESET_MAX_SIZE}.`,
    );
  }
  input.safeZones.forEach((zone, index) => {
    const which = `Safe zone ${index + 1}`;
    const { top, right, bottom, left } = zone.margins;
    if (!zone.name.trim()) {
      problems.push(`${which} needs a name.`);
    }
    if (![top, right, bottom, left].every(isMargin)) {
      problems.push(`${which}: margins must be whole pixels, 0 or more.`);
    } else if (left + right >= input.width || top + bottom >= input.height) {
      problems.push(`${which}: the margins leave nothing visible.`);
    }
  });
  return problems;
}

/** A saved preset as the library lists it. Its safe zones fit any canvas of its exact ratio. */
export function createCustomPreset(
  id: string,
  input: CustomCanvasPresetInput,
): CanvasSizePreset {
  const size = { width: input.width, height: input.height };
  return {
    id,
    channel: CUSTOM_CHANNEL,
    group: CUSTOM_CHANNEL,
    name: input.name.trim(),
    ...size,
    safeZones: input.safeZones.map((zone, index) => ({
      id: `${id}-safe-zone-${index + 1}`,
      label: zone.name.trim(),
      ratio: size,
      frame: size,
      margins: { ...zone.margins },
      covered: [],
      mirrorsForRightToLeft: false,
    })),
  };
}

/** The form a saved preset is stored in, read back from `preset`. */
export function toCustomPresetInput(
  preset: CanvasSizePreset,
): CustomCanvasPresetInput {
  return {
    name: preset.name ?? "",
    width: preset.width,
    height: preset.height,
    safeZones: preset.safeZones.map((zone) => ({
      name: zone.label,
      margins: { ...zone.margins },
    })),
  };
}

/**
 * Saved presets read back from storage. Anything that is not a valid preset is
 * dropped, so a damaged entry can't break the canvas size dialog.
 */
export function parseCustomPresets(stored: unknown): CanvasSizePreset[] {
  if (!Array.isArray(stored)) {
    return [];
  }
  return stored.flatMap((entry) => {
    const input = readStoredPreset(entry);
    return input && customPresetProblems(input.preset).length === 0
      ? [createCustomPreset(input.id, input.preset)]
      : [];
  });
}

function readStoredPreset(
  entry: unknown,
): { id: string; preset: CustomCanvasPresetInput } | null {
  if (
    !isRecord(entry) ||
    typeof entry.id !== "string" ||
    typeof entry.name !== "string" ||
    typeof entry.width !== "number" ||
    typeof entry.height !== "number" ||
    !Array.isArray(entry.safeZones)
  ) {
    return null;
  }
  const safeZones = entry.safeZones.map((zone: unknown) => {
    if (!isRecord(zone) || !isRecord(zone.margins)) {
      return null;
    }
    const { top, right, bottom, left } = zone.margins;
    if (
      typeof zone.name !== "string" ||
      typeof top !== "number" ||
      typeof right !== "number" ||
      typeof bottom !== "number" ||
      typeof left !== "number"
    ) {
      return null;
    }
    return { name: zone.name, margins: { top, right, bottom, left } };
  });
  if (safeZones.some((zone) => zone === null)) {
    return null;
  }
  return {
    id: entry.id,
    preset: {
      name: entry.name,
      width: entry.width,
      height: entry.height,
      safeZones: safeZones as CustomCanvasPresetInput["safeZones"],
    },
  };
}

function standard(
  id: string,
  group: string,
  width: number,
  height: number,
  name?: string,
): CanvasSizePreset {
  return {
    id,
    channel: STANDARD_CHANNEL,
    group,
    name,
    width,
    height,
    safeZones: [],
  };
}

function isSize(n: number): boolean {
  return (
    Number.isInteger(n) &&
    n >= CUSTOM_PRESET_MIN_SIZE &&
    n <= CUSTOM_PRESET_MAX_SIZE
  );
}

function isMargin(n: number): boolean {
  return Number.isInteger(n) && n >= 0;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}
